test('dashboard counts all statuses', () => {
  const inv1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });

  const inv2 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-08',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  const issued2 = issueInvoice(inv2.value, ['INV-2026-0001']);

  const inv3 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-09',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  const issued3 = issueInvoice(inv3.value, ['INV-2026-0002']);
  const partial3 = recordPayment(issued3.value, { amount: 5000, date: '2026-10-10' });

  const inv4 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-10',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  const issued4 = issueInvoice(inv4.value, ['INV-2026-0003']);
  const paid4 = recordPayment(issued4.value, { amount: 9771, date: '2026-10-11' });

  const dashboard_ = dashboard([inv1.value, issued2.value, partial3.value, paid4.value], '2026-10-31');
  assert.equal(dashboard_.counts.draft, 1);
  assert.equal(dashboard_.counts.issued, 1);
  assert.equal(dashboard_.counts.partially_paid, 1);
  assert.equal(dashboard_.counts.paid, 1);
});

test('dashboard calculates outstanding correctly', () => {
  const inv1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  });
  const issued1 = issueInvoice(inv1.value, []);

  const inv2 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-08',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  const issued2 = issueInvoice(inv2.value, ['INV-2026-0001']);
  const partial2 = recordPayment(issued2.value, { amount: 5000, date: '2026-10-09' });

  const dashboard_ = dashboard([issued1.value, partial2.value], '2026-10-31');
  const expected = invoiceTotals(issued1.value).total + (invoiceTotals(partial2.value).total - 5000);
  assert.equal(dashboard_.outstanding, expected);
});

test('dashboard excludes draft and paid from outstanding', () => {
  const draft = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });

