});

test('dashboard overdue has count and amount', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
    terms: 'NET14',
  });
  const issued = issueInvoice(inv.value, []);
  const dashboard_ = dashboard([issued.value], '2026-10-20');
  assert.equal(typeof dashboard_.overdue.count, 'number');
  assert.equal(typeof dashboard_.overdue.amount, 'number');
  assert.equal(dashboard_.overdue.count, 1);
  assert(dashboard_.overdue.amount > 0);
});

test('dashboard topCustomers returns top 3', () => {
  const invoices = [];
  for (let i = 1; i <= 5; i++) {
    const cid = `C-${String(i).padStart(3, '0')}`;
    const inv = createInvoice({
      customerId: cid,
      issueDate: '2026-10-07',
      lines: [{ sku: 'DES-HOUR', qty: i }],
    });
    invoices.push(issueInvoice(inv.value, invoices.map((x) => x.number).filter(Boolean)).value);
  }

  const dashboard_ = dashboard(invoices, '2026-10-31');
  assert.equal(dashboard_.topCustomers.length, 3);
  assert(dashboard_.topCustomers[0].due >= dashboard_.topCustomers[1].due);
  assert(dashboard_.topCustomers[1].due >= dashboard_.topCustomers[2].due);
});

test('dashboard topCustomers sorted highest first', () => {
  const inv1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
