  });
  const issued1 = issueInvoice(inv1.value, []);

  const inv2 = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 3 }],
  });
  const issued2 = issueInvoice(inv2.value, ['INV-2026-0001']);

  const dashboard_ = dashboard([issued1.value, issued2.value], '2026-10-31');
  assert.equal(dashboard_.topCustomers[0].customerId, 'C-002');
  assert.equal(dashboard_.topCustomers[1].customerId, 'C-001');
});

